package cn.deque;
import android.app.*;import android.os.*;import android.database.sqlite.*;import org.json.*;
public class BackupCheck extends Instrumentation{public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle r=new Bundle();try{SQLiteDatabase db=SQLiteDatabase.create(null);db.execSQL("CREATE TABLE queues(id TEXT PRIMARY KEY,name TEXT,tail INTEGER,updated INTEGER,deleted INTEGER,reminderMinutes INTEGER,position INTEGER DEFAULT 0)");db.execSQL("CREATE TABLE tasks(id TEXT PRIMARY KEY,queueId TEXT,title TEXT,position INTEGER,state INTEGER,updated INTEGER,completed INTEGER,notes TEXT,deadline INTEGER)");db.execSQL("CREATE TABLE preferences(key TEXT PRIMARY KEY,value INTEGER)");db.execSQL("INSERT INTO queues VALUES('q','queue',1,1,0,60,0)");db.execSQL("INSERT INTO tasks VALUES('t','q','title',1024,1,2,3,'notes',4000)");db.execSQL("INSERT INTO preferences VALUES('tail',0)");JSONObject before=Backup.exportData(db);Backup.importData(db,before);JSONObject after=Backup.exportData(db);if(after.getJSONArray("queues").length()!=2||after.getJSONArray("tasks").length()!=2)throw new Exception("counts");JSONObject task=after.getJSONArray("tasks").getJSONObject(1);if(!task.getString("notes").equals("notes")||task.getLong("completed")!=3||task.getLong("deadline")!=4000||task.getString("queueId").equals("q"))throw new Exception("fields/reference");JSONObject bad=new JSONObject(before.toString());bad.getJSONArray("tasks").getJSONObject(0).put("queueId","missing");boolean rejected=false;try{Backup.importData(db,bad);}catch(Exception e){rejected=true;}if(!rejected||Backup.exportData(db).getJSONArray("tasks").length()!=2)throw new Exception("invalid import");db.close();r.putString("stream","PASS backup roundtrip, duplicate IDs remapped, metadata, invalid reference rejected without mutation");finish(Activity.RESULT_OK,r);}catch(Exception e){r.putString("stream","FAIL "+e);finish(Activity.RESULT_CANCELED,r);}}}
